"""Build reviewable summaries from completed, immutable integration observations."""
import argparse,hashlib,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]

def save(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2)+'\n')
def identity(p):b=p.read_bytes();return {'path':str(p.relative_to(ROOT)),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def stats(values):return {'median':statistics.median(values),'min':min(values),'max':max(values),'samples':len(values)}
def common(p,validation,provenance):
 save(p.parent/'raw-identity.json',identity(p));save(p.parent/'validation.json',validation);save(p.parent/'provenance.json',provenance)
def workspace(p):
 d=json.loads(p.read_text());assert d['status']=='complete' and d['frozen_inputs_verified_after'];rows=d['observations'];summary={'cases':{},'timed_operation_sums_ms':{},'sampled_worker_pss_mib':{}}
 for name in d['oracles']:
  summary['cases'][name]={}
  for mode in ['shared','independent','ninja-ccache']:
   rr=[r for r in rows if r['scenario']==name and r['mode']==mode]
   assert rr and all(r['correct'] for r in rr)
   summary['cases'][name][mode]={key:stats([r[field]*factor for r in rr]) for key,field,factor in [('complete_ms','ns',1e-6),('editor_ms','editor_ready_ns',1e-6),('build_ms','build_ready_ns',1e-6),('cpu_ms_estimate','cpu_seconds_estimate',1e3)]}
   summary['cases'][name][mode]['compiled_targets']=[len(r['build_dirty']) if r['build_dirty'] is not None else None for r in rr]
 for mode in ['shared','independent','ninja-ccache']:
  rr=[r for r in rows if r['mode']==mode];blocks=sorted({r['block'] for r in rr});summary['timed_operation_sums_ms'][mode]=stats([sum(r['ns'] for r in rr if r['block']==b)/1e6 for b in blocks]);summary['sampled_worker_pss_mib'][mode]=stats([sum(v['Pss_kib'] for v in r['worker_memory'])/1024 for r in rr])
 save(p.parent/'summary.json',summary)
 common(p,{'passed':True,'workflow_operations':len(rows),'targets_per_operation':d['compile_units'],'object_checks':len(rows)*d['compile_units'],'depfile_checks':len(rows)*d['compile_units'],'executable_checks':len(rows),'symbol_index_checks':len(rows)*d['compile_units'],'full_oracle_generations':len(d['oracles']),'stale_generation_rejections':sum(r['stale_rejected'] is True for r in rows),'unit_test_methods':4,'source_pins_verified_after':True}, {'project':d['project'],'archive_sha256':d['archive_sha256'],'implementation_sha256':d['implementation'],'fixed_sdk_and_tool_count':len(d['fixed_sdk_and_tools']),'fixed_sdk_and_tool_manifest_sha256':hashlib.sha256(json.dumps(d['fixed_sdk_and_tools'],sort_keys=True).encode()).hexdigest(),'environment_sha256':d['environment_sha256'],'preparation_seconds':d['preparation_ns']/1e9,'oracle_seconds':sum(o['preparation_ns'] for o in d['oracles'].values())/1e9,'warmups':d['warmups'],'cache_policy':'Independent traces from baseline-only restored ccache seed; native observations/index retain their latest state and IR stores one latest object per context, while ccache retains encountered versions. Same repeated generations per trace; no cross-trace native retention.','scope':'One shared native worker versus concurrent build/index workers; explicit fixture membership hints for Ninja; external baseline-positive SDK/environment fixed, not complete arbitrary-effect capture. Source and tools frozen. Current worker PSS excludes controller/peaks, and CPU uses coarse native process ticks.'})
 lines=['# Sharing current compiler observations with a real query consumer','','The fixture builds all 33 production Ninja translation units and runs project declaration-record queries against the same admitted generation. Independent cached consumers run concurrently; Ninja + ccache has a separate cached index consumer. Each row is a median of three blocks on one laptop.','','| Operation | Shared complete | Independent complete | Ninja + ccache complete | Shared editor | Independent editor |','| --- | ---: | ---: | ---: | ---: | ---: |']
 for name,m in summary['cases'].items():lines.append('| '+name.replace('_',' ')+' | '+' | '.join(f"{m[mode]['complete_ms']['median']:.2f} ms" for mode in ['shared','independent','ninja-ccache'])+' | '+f"{m['shared']['editor_ms']['median']:.2f} ms | {m['independent']['editor_ms']['median']:.2f} ms |")
 lines+=['','A final-current editor result and a completed executable have different readiness times. The first shared controller publishes only after compilation and linking; earlier handoff is not implemented. An independent query can finish while the build continues. Full physical CLI objects, depfiles and executables, and uncached physical syntax/index results validate every operation. The burst rejects stale generations but does not cancel an already-running compiler pass.','','Noop/unchanged targets reuse validated facts and objects. Include rewiring refreshes observations even if an IR hit is possible; debug metadata can make a nominally equivalent include change alter object bytes. The configuration case uses a new context and conservatively reparses all targets. The exact-input cache remains an important baseline.','','Ninja receives an explicit single-probe-TU invalidation hint for optional-header appearance/removal and include shadowing. This fixture adapter is charged inside the operation; ccache uses preprocessor mode for these events after a stale direct hit was rejected. This is not a generic negative-dependency importer. Each trace restores a baseline-only ccache seed. Physical input edit application, native admission, scanning, queries, compilation and required linking are timed. Initial preparation, reference builds, warmup and correctness reads are outside those clocks and separately recorded.','','Worker memory values are current samples, not peaks or enforced budgets. CPU sums coarse persistent-host ticks with controller and completed-child usage. No dependency-aware retention policy, multiple in-flight immutable generations or concurrent mutable Clang AST sharing is implemented.','','[Summary](summary.json), [validation](validation.json), [provenance](provenance.json), [raw identity](raw-identity.json), [reproduction](../../README.md).']
 (p.parent/'REPORT.md').write_text('\n'.join(lines)+'\n')
 return summary

def simd(p):
 d=json.loads(p.read_text());assert d['status']=='complete' and d['frozen_inputs_verified_after'];summary={'cases':{}}
 for c in d['cases']:
  m=c['measurement'];summary['cases'][c['label']]={'roots':c['fixture']['roots'],'rows':m['rows'],'changed':m['changed'],'matrix_bytes':m['matrix_bytes'],'csr_bytes':m['csr_bytes'],'csr_prepare_ns':m['csr_prepare_ns'],'modes':{str(mode):stats([v['ns']/v['operations'] for v in m['observations'] if v['mode']==mode]) for mode in sorted({v['mode'] for v in m['observations']})}}
 save(p.parent/'summary.json',summary)
 common(p,{'passed':True,'fixtures':len(d['cases']),'query_outputs_per_mode':sum(c['measurement']['validated_queries_per_mode'] for c in d['cases']),'exact_mode_query_comparisons':sum(c['measurement']['validated_queries_per_mode']*len({r['mode'] for r in c['measurement']['observations']}) for c in d['cases']),'unit_test_methods':2,'source_input_binary_pins_verified_after':True}, {'scope':d['scope'],'fixture_preparation_ns':d['fixture_preparation_ns'],'implementation_and_tool_sha256':{Path(k).name:v for k,v in d['implementation_and_tools'].items()},'clock':'Native warm batch wall time; opaque shared-library calls, output clear/dispatch/ID checks and small checksum included. Seven shuffled blocks per fixture.','controls':'Odin optimized loops, word tiling, AVX2/AVX512; native C++ CSR list representation. No strict scalar claim. Native-target and generic-library matrices compared within their own run.','device_memory':'Retained input payload sizes and CSR preparation are measured; no RSS quota or machine-cold claim.'})
 lines=['# Vector unions versus optimized loops and sparse lists','','The operation unions masks of changed observations. Values are nanoseconds per warm native operation, median of seven shuffled blocks; the portable loop may already auto-vectorize. Generated cases are labelled. Every mode produces the same complete output for all prepared queries.','','| Fixture | Optimized loop | Word tiled | SIMD 4 lanes | SIMD 8 lanes | CSR lists |','| --- | ---: | ---: | ---: | ---: | ---: |']
 for label,c in summary['cases'].items():lines.append('| '+label+' | '+' | '.join(f"{c['modes'][str(m)]['median']:.1f}" if str(m) in c['modes'] else 'unsupported' for m in [0,1,2,3,4])+' |')
 lines+=['','The captured graph contains only 33 targets, so each row fits one 64-bit word and explicit wider kernels use their scalar tails. Dense generated relations test contiguous mask work; sparse CSR is a separate, strong algorithm/representation control. A vector improvement on wide masks does not establish a complete compiler speedup.','','Fixture construction and CSR conversion are separately charged in metadata. Timed native batches cycle prepared queries and consume output values, amortizing Python ABI crossings. Validation, output clear and a small checksum remain inside those clocks. Payload sizes are not process-memory limits. Read the native-target matrix alongside the generic build before attributing a win to hand-written SIMD. The generic eight-lane source lowers into narrower instructions; native code generation includes actual ZMM instructions (see the build evidence in the reproduction guide).','','[Summary](summary.json), [validation](validation.json), [provenance](provenance.json), [raw identity](raw-identity.json), [reproduction](../../README.md).']
 (p.parent/'REPORT.md').write_text('\n'.join(lines)+'\n');return summary

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('kind',choices=['workspace','simd']);p.add_argument('raw',type=Path);a=p.parse_args();globals()[a.kind](a.raw.resolve())
